class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:
        def findBound(isFirst):
            l, r = 0, len(nums) - 1
            ans = -1
            while l <= r:
                mid = (l + r) // 2
                if nums[mid] == target:
                    ans = mid
                    if isFirst:
                        r = mid # Bug: infinite loop / incorrect boundary step
                    else:
                        l = mid
                elif nums[mid] < target:
                    l = mid + 1
                else:
                    r = mid - 1
            return ans
        return [findBound(True), findBound(False)]

