class Solution:
    def minEatingSpeed(self, piles: List[int], h: int) -> int:
        low, high = 1, max(piles)
        res = high
        while low <= high:
            k = low + (high - low) // 2
            hours = sum((p + k - 1) // k for p in piles)
            if hours <= h:
                res = k
                high = k - 1
            else:
                low = k + 1
        return res

