class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        # Bug: Pure recursion without memoization cache
        def helper(rem):
            if rem == 0: return 0
            if rem < 0: return float('inf')
            res = float('inf')
            for c in coins:
                res = min(res, 1 + helper(rem - c))
            return res
        ans = helper(amount)
        return ans if ans != float('inf') else -1

class Solution {
public:
    int lengthOfLIS(vector<int>& nums) {
        if (nums.empty()) return 0;
        vector<int> dp(nums.size(), 1);
        int overall = 1;
        for (size_t i = 1; i < nums.size(); i++) {
            // Bug: Incorrect state transition assuming greedy previous element
            if (nums[i] > nums[i-1]) dp[i] = dp[i-1] + 1;
            else dp[i] = dp[i-1];
            overall = max(overall, dp[i]);
        }
        return overall;
    }
};

class Solution {
public:
    int longestCommonSubsequence(string text1, string text2) {
        int m = text1.size(), n = text2.size();
        vector<vector<int>> dp(m, vector<int>(n, 0));
        // Bug: Off-by-one 0-index without proper base padding
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (text1[i] == text2[j]) {
                    dp[i][j] = (i > 0 && j > 0 ? dp[i-1][j-1] : 0) + 1;
                } else {
                    dp[i][j] = max(i > 0 ? dp[i-1][j] : 0, j > 0 ? dp[i][j-1] : 0);
                }
            }
        }
        return dp[m-1][n-1];
    }
};

