class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        if not grid: return 0
        m, n = len(grid), len(grid[0])
        count = 0
        for r in range(m):
            for c in range(n):
                if grid[r][c] == '1':
                    count += 1
                    q = collections.deque([(r, c)])
                    while q:
                        curr_r, curr_c = q.popleft()
                        grid[curr_r][curr_c] = '0' # Bug: Marking visited AFTER pop instead of push causes huge duplicates
                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nr, nc = curr_r + dr, curr_c + dc
                            if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == '1':
                                q.append((nr, nc))
        return count

class Solution {
public:
    bool isBipartite(vector<vector<int>>& graph) {
        int n = graph.size();
        vector<int> color(n, 0);
        // Bug: Only starting traversal from node 0, failing on disconnected graphs
        queue<int> q;
        q.push(0);
        color[0] = 1;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : graph[u]) {
                if (color[v] == 0) {
                    color[v] = -color[u];
                    q.push(v);
                } else if (color[v] == color[u]) {
                    return false;
                }
            }
        }
        return true;
    }
};

class Solution:
    def canFinish(self, numCourses: int, prerequisites: List[List[int]]) -> bool:
        adj = collections.defaultdict(list)
        for dest, src in prerequisites:
            adj[src].append(dest)

        visited = set()
        def has_cycle(node):
            if node in visited: # Bug: Doesn't differentiate recursion stack vs fully explored, causing false positive / infinite loop
                return True
            visited.add(node)
            for neighbor in adj[node]:
                if has_cycle(neighbor): return True
            return False

        for i in range(numCourses):
            if has_cycle(i): return False
        return True

