class Solution:
    def trap(self, height: List[int]) -> int:
        if not height: return 0
        l, r = 0, len(height) - 1
        l_max, r_max = height[l], height[r]
        ans = 0
        while l < r:
            if height[l] < height[r]:
                ans += l_max - height[l] # Bug: water added before updating l_max causes negative/wrong values
