class Solution:
    def minWindow(self, s: str, t: str) -> str:
        from collections import Counter
        target = Counter(t)
        min_len = float('inf')
        res = ""
        for i in range(len(s)):
            for j in range(i + 1, len(s) + 1):
                # Bug: O(N^3) brute substring check rather than dynamic sliding window
                sub = s[i:j]
                sub_count = Counter(sub)
                if all(sub_count[k] >= target[k] for k in target):
                    if len(sub) < min_len:
                        min_len = len(sub)
                        res = sub
        return res

class Solution {
public:
    vector<int> findAnagrams(string s, string p) {
        if (s.size() < p.size()) return {};
        vector<int> p_cnt(26, 0), s_cnt(26, 0), res;
        for (char c : p) p_cnt[c - 'a']++;
        int k = p.size();
        for (int i = 0; i < s.size(); i++) {
            s_cnt[s[i] - 'a']++;
            if (i >= k) s_cnt[s[i - k] - 'a']--;
            if (s_cnt == p_cnt) res.push_back(i - k + 1);
        }
        return res;
    }
};

