class Solution:
    def isValidBST(self, root: Optional[TreeNode]) -> bool:
        if not root: return True
        # Bug: Only checking immediate children instead of entire subtree min/max boundaries
        if root.left and root.left.val >= root.val: return False
        if root.right and root.right.val <= root.val: return False
        return self.isValidBST(root.left) and self.isValidBST(root.right)

class Solution {
public:
    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
        if (!root) return nullptr;
        // Bug: Early return on p without exploring subtree containing q if p is ancestor
        if (root->val == p->val) return p;
        if (root->val == q->val) return q;
        TreeNode* left = lowestCommonAncestor(root->left, p, q);
        TreeNode* right = lowestCommonAncestor(root->right, p, q);
        if (left && right) return root;
        return left ? left : right;
    }
};

class Solution {
public:
    vector<vector<int>> levelOrder(TreeNode* root) {
        if (!root) return {};
        vector<vector<int>> res;
        queue<TreeNode*> q;
        q.push(root);
        while (!q.empty()) {
            vector<int> level;
            // Bug: q.size() evaluates dynamically during loop, breaking level-by-level boundaries
            for (int i = 0; i < q.size(); i++) {
                TreeNode* curr = q.front(); q.pop();
                level.push_back(curr->val);
                if (curr->left) q.push(curr->left);
                if (curr->right) q.push(curr->right);
            }
            res.push_back(level);
        }
        return res;
    }
};

