class Solution {
public:
    int jump(vector<int>& nums) {
        int jumps = 0, cur_end = 0, cur_farthest = 0;
        for (int i = 0; i < nums.size(); i++) { // Bug: looping up to n-1 instead of n-2 adds extra redundant jump
            cur_farthest = max(cur_farthest, i + nums[i]);
            if (i == cur_end) {
                jumps++;
                cur_end = cur_farthest;
            }
        }
        return jumps;
    }
};

