class Solution:
    def eraseOverlapIntervals(self, intervals: List[List[int]]) -> int:
        # Bug: Sorting by start time instead of end time
        intervals.sort(key=lambda x: x[0])
        count = 0
        prev = intervals[0]
        for curr in intervals[1:]:
