class Solution {
public:
    int canCompleteCircuit(vector<int>& gas, vector<int>& cost) {
        int curr_tank = 0, start_idx = 0;
        for (int i = 0; i < gas.size(); i++) {
            curr_tank += gas[i] - cost[i];
            if (curr_tank < 0) {
                start_idx = i + 1;
                curr_tank = 0;
            }
        }
        // Bug: missing check whether total_gas >= total_cost
